pseudocode:
let record = [];
for (let op of ops) {
  if (op === '+') {
    record.push(record[record.length - 1] + record[record.length - 2]);
  } else if (op === 'D') {
    record.push(record[record.length - 1] * 2);
  } else if (op === 'C') {
    record.pop();
  } else {
    record.push(Number(op));
  }
}
